import { User } from '../shared/types'

function isAuthorizedToAutoApply(user: User | null): {
  isAuthorized: boolean
  isLoggedIn: boolean
  message?: string
} {
  if (!user) return { isAuthorized: false, isLoggedIn: false, message: 'User is not logged in' }

  if (!user.autoApplyEnabled) {
    return {
      isLoggedIn: true,
      isAuthorized: false,
      message: 'User does not have auto apply plan activated',
    }
  }

  return { isLoggedIn: true, isAuthorized: true }
}

export default isAuthorizedToAutoApply
