import { User } from '../shared/types'
import { getUserBaseDomain } from '../shared/helpers'

const getPaywallUrl = (user: User): string => {
  const base = getUserBaseDomain(user)
  if (!user.autoApplyEnabled) {
    return `${base}/app/billing/plans?referrerPage=auto-apply`
  }

  const isPaidUser =
    !user?.billingInfo?.cancelledAt &&
    !user?.billingInfo?.nextPaymentAt &&
    ((user?.billingInfo?.recurringAmount as unknown as string) === 'USD0.0' ||
      !user?.billingInfo?.recurringAmount)
      ? false
      : true

  if (isPaidUser) {
    return `${base}/app/billing/payment?plan=20_auto_appy_credits_promo&on_success_redirect=/app/job-tracking?show_credit_modal=true`
  }

  return `${base}/app/billing/payment?plan=20_credits_autoapply&on_success_redirect=/app/job-tracking?show_credit_modal=true`
}
export default getPaywallUrl
