import isAuthorizedToAutoApply from '../helpers/autoApplyAccess'
import getPaywallUrl from '../helpers/getAutoApplyPaywall'
import {
  CAREER_IO_APP_DOMAIN,
  ENDPOINTS,
  MAIN_SIGNIN_URL,
  RESUME_IO_DOMAIN,
  STATUSES,
} from '../shared/constants'
import { JobBoardPost, User, UserAccountResponse } from '../shared/types'
import { TAB_MESSAGE_TYPES } from './constants'

let intervalId: number | null = null
const INTERVAL_PERIOD = 60 * 60 * 1000

// Function to run when the extension is installed
async function onInstalled(details) {
  if (details.reason === 'install') {
    // Inject content script into already open tabs
    chrome.tabs.query({}, function (tabs) {
      tabs.forEach(function (tab) {
        if (tab.url?.startsWith('chrome://')) return undefined

        chrome.scripting.executeScript({
          target: { tabId: tab.id as number },
          files: ['content.js'],
        })
      })
    })
    // When installed
    chrome.tabs.create({ url: MAIN_SIGNIN_URL })
  }
  await startUserDataSync(false)
}

chrome.runtime.onInstalled.addListener(onInstalled)
chrome.runtime.onMessage.addListener(async (request, sender, sendResponse) => {
  if (request.type === TAB_MESSAGE_TYPES.auth) {
    chrome.tabs.query({}, function (tabs) {
      tabs.forEach((tab) => {
        const id = tab.id as number
        chrome.tabs.sendMessage(
          id,
          {
            type: TAB_MESSAGE_TYPES.sendJwt,
            token: request.token,
            refreshToken: request.refreshToken,
            baseDomain: request.baseDomain,
            isRioUser: request.isRioUser,
          },
          function (response) {
            if (!chrome.runtime.lastError) {
              // if you have any response
              console.log('Response', response)
            }
          },
        )
      })
    })
  }

  if (request.type === TAB_MESSAGE_TYPES.autoApply) {
    const { url, jobDetails, buttonIndex } = request
    const response = await autoApply(url, jobDetails)
    const urlObj = new URL(url)

    const baseUrl = urlObj.origin + urlObj.pathname

    chrome.tabs.query({ url: url.includes('www.seek.') ? `${baseUrl}*` : url }, function (tabs) {
      tabs.forEach((tab) => {
        const id = tab.id as number
        chrome.tabs.sendMessage(
          id,
          {
            type: TAB_MESSAGE_TYPES.autoApplyResponse,
            response: { ...response, buttonIndex },
          },
          function (response) {
            if (!chrome.runtime.lastError) {
              // if you have any response
              console.log('Response', response)
            }
          },
        )
      })
    })
  }
})

function startPeriodicTask() {
  if (!intervalId) {
    intervalId = setInterval(checkAndRefreshUserData, INTERVAL_PERIOD)
  }
}

function stopPeriodicTask() {
  if (intervalId) {
    clearInterval(intervalId)
    intervalId = null
  }
}

async function startUserDataSync(syncImmediately = true) {
  if (syncImmediately) {
    await checkAndRefreshUserData()
  }
  startPeriodicTask()
}

chrome.runtime.onStartup.addListener(startUserDataSync)

chrome.runtime.onSuspend.addListener(() => {
  stopPeriodicTask()
})

async function checkAndRefreshUserData() {
  const { lastRefresh } = await chrome.storage.local.get(['lastRefresh'])
  const now = new Date().getTime()

  if (!lastRefresh || now - lastRefresh >= INTERVAL_PERIOD) {
    performUserDataRefresh(now)
  }
}

async function performUserDataRefresh(refreshDate: number) {
  const { jtrack_user: user } = await chrome.storage.local.get(['jtrack_user'])

  if (!user || !user.refreshToken) return

  const baseDomain = user.baseDomain
    ? user.baseDomain
    : user.isRioUser
    ? RESUME_IO_DOMAIN
    : CAREER_IO_APP_DOMAIN
  const body = {
    jwt_token: user.token,
    refresh_token: user.refreshToken,
  }

  const tokenResponse = await fetch(`${baseDomain}/api/browser-extension/auth/refresh-token`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${user.token}`,
    },
    body: JSON.stringify(body),
  })

  if (!tokenResponse.ok) {
    return
  }

  const { token, refresh_token, success } = await tokenResponse.json()

  if (!success) {
    return
  }

  const userResponse = await fetch(`${baseDomain}/api/app/account`, {
    method: 'GET',
    headers: {
      Authorization: `Bearer ${token}`,
    },
  })

  if (!userResponse.ok) {
    return
  }

  const {
    success: userSuccess,
    jwt,
    jwtExpiresAt,
    user: updatedUserData,
  } = (await userResponse.json()) as UserAccountResponse

  if (!userSuccess) {
    return
  }

  const updatedUser: User = {
    firstName: updatedUserData.firstName,
    lastName: updatedUserData.lastName,
    hasPremium: updatedUserData.hasPremiumFeatures,
    autoApplyEnabled: !!updatedUserData.scopes?.autoApply,
    autoApplyCreditsCount:
      typeof updatedUserData.scopes.autoApply !== 'boolean'
        ? updatedUserData.scopes.autoApply.creditCount
        : undefined,
    autoApplyCreditsUsed:
      typeof updatedUserData.scopes.autoApply !== 'boolean'
        ? updatedUserData.scopes.autoApply.creditCountUsed
        : undefined,
    baseDomain,
    isRioUser: updatedUserData.isRioUser,
    billingInfo: updatedUserData.billingInfo,
    token,
    refreshToken: refresh_token,
    jwt,
    jwtExpiresAt,
  }

  await chrome.storage.local.set({ jtrack_user: updatedUser, lastRefresh: refreshDate })
}

async function autoApply(url: string, jobDetails: JobBoardPost) {
  if (!url) return { error: true, success: false }
  const { jtrack_user: user } = await chrome.storage.local.get(['jtrack_user'])
  const { isLoggedIn } = isAuthorizedToAutoApply(user)
  if (!isLoggedIn) return { error: true, success: false }

  const baseDomain = user.baseDomain
    ? user.baseDomain
    : user.isRioUser
    ? RESUME_IO_DOMAIN
    : CAREER_IO_APP_DOMAIN
  const saveJobUrl = `${baseDomain}${ENDPOINTS.ADD_JOB}`

  try {
    const headers = {
      Authorization: `Bearer ${user?.token}`,
      'Content-Type': 'application/json',
    }

    const jobData = {
      job: {
        logo: null,
        title: jobDetails?.title || 'Not specified',
        company: jobDetails?.company || 'Not specified',
        link: jobDetails?.link || url,
        location: jobDetails?.location,
        status: STATUSES.autoApply,
        description: jobDetails?.description,
        notes: '',
      },
    }
    const saveResponse = await fetch(saveJobUrl, {
      body: JSON.stringify(jobData),
      method: 'post',
      headers,
    })

    if (saveResponse.status === 403) {
      return {
        error: true,
        success: false,
        redirectTo: getPaywallUrl(user),
      }
    }
    if (saveResponse.status !== 201) {
      return { error: true, success: false }
    }
    return { error: false, success: true, baseDomain }
  } catch (error) {
    return { error: true, success: false }
  }
}
