import { ICoverLetter, IResume } from './types'

export const isProd = process.env.NODE_ENV === 'production'

export const EXTENSION_LOGIN_PATH = `/app/browser-extension/auth?chrome_extension=true`

// check if needed
export const SIGN_IN_PATH = `/app/auth/sign-in?chrome_extension=true`

export const RESUME_IO_DOMAIN = isProd ? 'https://resume.io' : 'https://staging.resume.io'
export const CAREER_IO_APP_DOMAIN = isProd ? 'https://career.io' : 'https://staging.career.io'
export const CAREER_IO_CAREER_MINDS_APP_DOMAIN = isProd
  ? 'https://careerio.careerminds.com'
  : 'https://staging-careerio.careerminds.com'
export const CAREER_IO_TR_APP_DOMAIN = isProd
  ? 'https://careerio.topresume.com'
  : 'https://staging.topresume.com'
export const TOP_CV_APP_DOMAIN = isProd
  ? 'https://careerio.topcv.com/'
  : 'https://staging.careerio.topcv.com/'
export const SSR_HOST = isProd ? 'https://ssr.resume.tools' : 'https://rio-ssr-server.vercel.app'

export const MAIN_SIGNIN_URL = `${CAREER_IO_APP_DOMAIN}${EXTENSION_LOGIN_PATH}`

export const SUPPORTED_APP_DOMAINS = [
  CAREER_IO_APP_DOMAIN,
  RESUME_IO_DOMAIN,
  CAREER_IO_TR_APP_DOMAIN,
  CAREER_IO_CAREER_MINDS_APP_DOMAIN,
  TOP_CV_APP_DOMAIN,
]

export const ENDPOINTS = {
  AUTHENTICATE_USER: `/api/browser-extension/account`,
  AUTHENTICATE_USER_WITH_PASSWORD: '/api/browser-extension/auth/password',
  SEND_OTP: `/api/browser-extension/auth/send-otp`,
  VERIFY_OTP: `/api/browser-extension/auth/verify-otp`,
  ADD_JOB: `/api/browser-extension/saved-jobs`,
  REFRESH_TOKEN: '/api/browser-extension/auth/refresh-token',
  SUGGEST: `/api/browser-extension/suggest`,
  GET_JOB_INFO: `/app/browser-extension/auth/fetch-job-details`,
  GET_USER_RESUMES: `/api/app/resumes`,
  GET_RESUME: (id: number) => `/api/app/resumes/${id}`,
  GET_USER_COVER_LETTERS: `/api/app/cover-letters`,
  GET_COVER_LETTER: (id: number) => `/api/app/cover-letters/${id}`,
  DOWNLOAD_PDF_DOCUMENT: (renderingToken: string, token: string, version: string) =>
    `${SSR_HOST}/to-pdf/${renderingToken}?token=${token}&version=${version}`,
  DOWNLOAD_TXT_RESUME: (id: number) => `${CAREER_IO_APP_DOMAIN}/api/app/resumes/${id}/txt-download`,
  USER_ACCOUNT: `/api/app/account`,
  EXTEND_ACCOUNT_JWT: (jwt: string) =>
    `${CAREER_IO_APP_DOMAIN}/api/app/account/extend-jwt?token=${jwt}`,
  GET_JOB_BOARD_CARDS: `/api/app/job-board/cards?prefill=false&location=Remote`,
}

export const DEFAULT_RESUME_NAME = (resume: IResume) =>
  `${resume.firstName}_${resume.lastName}_RESUME`

export const DEFAULT_COVER_LATTER_NAME = (coverLetter: ICoverLetter) =>
  `${coverLetter.senderName}_COVER_LETTER`

export const JOB_TRACKING_URL = (base = CAREER_IO_APP_DOMAIN) => `${base}/app/job-tracking`

export enum RESUME_FORMAT {
  PDF = 'pdf',
  TXT = 'txt',
}

